const filePath = '__FIXTURE_DIR__/employees.csv';
const content = fs.readFileSync(filePath, 'utf8');
const lines = content.trim().split(/\r?\n/);
const headers = lines[0].split(',').map((s: string) => s.trim());
const rows = lines.slice(1).map((line: string) => {
  const values = line.split(',').map((s: string) => s.trim());
  const obj: { [key: string]: string } = {};
  headers.forEach((h: string, i: number) => {
    obj[h] = values[i];
  });
  return obj;
});

const employees = rows.map((r: { [key: string]: string }) => ({
  employee_id: Number(r.employee_id),
  name: r.name,
  department: r.department,
  salary: Number(r.salary),
  start_date: r.start_date,
  rating: Number(r.rating),
}));

function formatNumber(value: number, decimals: number): string {
  const fixed = value.toFixed(decimals);
  const [int, frac] = fixed.split('.');
  const sign = int.startsWith('-') ? '-' : '';
  const abs = sign ? int.slice(1) : int;
  const withCommas = abs.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  if (decimals > 0) {
    return `${sign}$${withCommas}.${frac}`;
  }
  return `${sign}$${withCommas}`;
}

