int split(char *line, char **fields, int max) {
    int n = 0;
    char *p = line;
    fields[n++] = p;
    while (*p) {
        if (*p == ',') {
            *p = 0;
            if (n < max) fields[n++] = p + 1;
        }
        p++;
    }
    return n;
}

char *trim(char *s) {
    while (*s && isspace((unsigned char)*s)) s++;
    char *end = s + strlen(s);
    while (end > s && isspace((unsigned char)end[-1])) end--;
