}

void print_int_part_comma(const char *int_part) {
    int len = strlen(int_part);
    char out[64];
    int out_len = 0;
    int count = 0;
    for (int i = len - 1; i >= 0; i--) {
        out[out_len++] = int_part[i];
        count++;
        if (count % 3 == 0 && i > 0) {
            out[out_len++] = ',';
        }
    }
    for (int i = out_len - 1; i >= 0; i--) {
        putchar(out[i]);
    }
}

