    char buf[64];
    snprintf(buf, sizeof(buf), "%.*f", decimals, value);
    char *dot = strchr(buf, '.');
    if (dot) {
        int int_len = dot - buf;
        char int_part[32];
        strncpy(int_part, buf, int_len);
        int_part[int_len] = 0;
        char frac_part[16];
        strncpy(frac_part, dot + 1, sizeof(frac_part) - 1);
        frac_part[sizeof(frac_part) - 1] = 0;
        printf("$");
        print_int_part_comma(int_part);
        printf(".%s", frac_part);
    } else {
        printf("$");
        print_int_part_comma(buf);
    }
}

