        let name = parts[1];
        let department = parts[2];
        let salary_str = parts[3];
        let salary: f64 = salary_str.parse().unwrap_or(0.0);
        let entry = dept_data.entry(department.to_string()).or_insert((0.0, 0));
        entry.0 += salary;
        entry.1 += 1;
        total_sum += salary;
        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name.to_string();
        }
    }

