import * as fs from "fs";

interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface Graph {
  nodes: string[];
  edges: Edge[];
}

function main(): void {
  const filePath = "__FIXTURE_DIR__/graph.json";
  const data = JSON.parse(fs.readFileSync(filePath, "utf8")) as Graph;
  const nodes = data.nodes;
  const edges = data.edges;

  const adj = new Map<string, { to: string; weight: number }[]>();
  for (const n of nodes) {
    adj.set(n, []);
  }
  for (const e of edges) {
    if (adj.has(e.from)) {
      adj.get(e.from)!.push({ to: e.to, weight: e.weight });
    }
    if (adj.has(e.to)) {
      adj.get(e.to)!.push({ to: e.from, weight: e.weight });
    }
  }

  const distances = new Map<string, number>();
  for (const n of nodes) {
    distances.set(n, Infinity);
  }
  distances.set("A", 0);

  const visited = new Set<string>();
  const queue: string[] = ["A"];

  while (queue.length > 0) {
    let current: string | undefined;
    let bestDist = Infinity;
    for (const n of queue) {
      const d = distances.get(n)!;
      if (d < bestDist) {
        bestDist = d;
        current = n;
      }
    }
    if (current === undefined) break;
    queue.splice(queue.indexOf(current), 1);
    if (visited.has(current)) continue;
    visited.add(current);
    const currentDist = distances.get(current)!;
    const neighbors = adj.get(current) || [];
    for (const edge of neighbors) {
      if (visited.has(edge.to)) continue;
      const newDist = currentDist + edge.weight;
      if (newDist < (distances.get(edge.to) ?? Infinity)) {
        distances.set(edge.to, newDist);
        if (!queue.includes(edge.to)) {
          queue.push(edge.to);
        }
      }
    }
  }

  const sortedNodes = [...nodes].sort();
  let output = "=== Shortest Paths from A ===\n\n";
