int read_command(const char *cmd, char **out) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return -1;
    size_t cap = 1024;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) { pclose(fp); return -1; }
    buf[0] = '\0';
    char chunk[1024];
    size_t n;
    while ((n = fread(chunk, 1, sizeof(chunk), fp)) > 0) {
        if (len + n + 1 > cap) {
            cap *= 2;
            char *newbuf = (char *)realloc(buf, cap);
            if (!newbuf) { free(buf); pclose(fp); return -1; }
            buf = newbuf;
        }
        memcpy(buf + len, chunk, n);
        len += n;
        buf[len] = '\0';
    }
    int err = ferror(fp);
    pclose(fp);
    if (err) { free(buf); return -1; }
    while (len > 0 && isspace((unsigned char)buf[len - 1])) {
        buf[--len] = '\0';
    }
    *out = buf;
    return 0;
}

int main(void) {
    char *hostname = NULL;
    char *os = NULL;
    char *arch = NULL;
    char *username = NULL;
    if (read_command("hostname", &hostname) != 0) return 1;
    if (read_command("uname -s", &os) != 0) { free(hostname); return 1; }
    if (read_command("uname -m", &arch) != 0) { free(hostname); free(os); return 1; }
    if (read_command("whoami", &username) != 0) { free(hostname); free(os); free(arch); return 1; }

    printf("{\n  \"hostname\": \"%s\",\n  \"os\": \"%s\",\n  \"architecture\": \"%s\",\n  \"username\": \"%s\"\n}", hostname, os, arch, username);

    free(hostname);
    free(os);
    free(arch);
    free(username);
    return 0;
}

import Foundation

func jsonEscape(_ value: String) -> String {
    var escaped = "\""
    for scalar in value.unicodeScalars {
        let v = scalar.value
        if v == 34 {
            escaped += "\\\""
        } else if v == 92 {
            escaped += "\\\\"
        } else if v == 10 {
            escaped += "\\n"
        } else if v == 13 {
            escaped += "\\r"
        } else if v == 9 {
            escaped += "\\t"
        } else if v == 8 {
            escaped += "\\b"
        } else if v == 12 {
            escaped += "\\f"
        } else if v < 0x20 {
            escaped += String(format: "\\u%04x", v)
        } else {
            if let scalar = UnicodeScalar(v) {
                escaped += String(scalar)
            }
        }
    }
    escaped += "\""
    return escaped
}

func runCommand(_ executable: String, _ arguments: [String]) -> String {
    let process = Process()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/" + executable)
    process.arguments = arguments
    let pipe = Pipe()
    process.standardOutput = pipe
    process.standardError = pipe
    do {
        try process.run()
        process.waitUntilExit()
    } catch {
        return ""
    }
    let data = pipe.fileHandleForReading.readDataToEndOfFile()
    let output = String(data: data, encoding: .utf8) ?? ""
    return output.trimmingCharacters(in: .whitespacesAndNewlines)
}

