func formatValue(_ v: Int) -> String {
    let s = "\(v)"
    let padding = 4 - s.count
    if padding > 0 {
        return String(repeating: " ", count: padding) + s
    } else {
        return s
    }
}

func formatRow(_ row: [Int]) -> String {
    let fields = row.map { formatValue($0) }
    return "  " + fields.joined(separator: " ")
}

func multiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let n = A.count
    let m = B[0].count
    let p = B.count
    var C = [[Int]]()
    for i in 0..<n {
        var row = [Int]()
        for j in 0..<m {
            var sum = 0
            for k in 0..<p {
                sum += A[i][k] * B[k][j]
            }
            row.append(sum)
        }
        C.append(row)
    }
    return C
}

func determinant(_ M: [[Int]]) -> Int {
    let n = M.count
    if n == 1 {
        return M[0][0]
    }
    if n == 2 {
        return M[0][0] * M[1][1] - M[0][1] * M[1][0]
    }
    var det = 0
    for c in 0..<n {
        var minor: [[Int]] = []
        for i in 1..<n {
            var row = [Int]()
            for j in 0..<n {
                if j != c {
                    row.append(M[i][j])
                }
            }
            minor.append(row)
        }
        let sign = (c % 2 == 0) ? 1 : -1
        det += sign * M[0][c] * determinant(minor)
    }
    return det
}

