function multiply(A: number[][], B: number[][]): number[][] {
  const n = A.length;
  const m = B[0].length;
  const p = A[0].length;
  const result: number[][] = Array.from({ length: n }, () => Array<number>(m).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      let sum = 0;
      for (let k = 0; k < p; k++) {
        sum += A[i][k] * B[k][j];
      }
      result[i][j] = sum;
    }
  }
  return result;
}

function determinant(mat: number[][]): number {
  const a = mat[0][0], b = mat[0][1], c = mat[0][2];
  const d = mat[1][0], e = mat[1][1], f = mat[1][2];
  const g = mat[2][0], h = mat[2][1], i = mat[2][2];
  return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
}

